def sp(s):
    s=re.sub(r'（[^）]*）','',s); s=re.sub(r'\([^)]*\)','',s)
    s=s.replace(' ','').replace('\n',''); return re.sub(r'　+','　',s)
def wrap_names(s):
    toks=re.split(r'（([^）]*)）',s); out=[]
    for i,t in enumerate(toks):
        if i%2==0:
            if t!='': out.append('⟪'+t.strip('　')+'⟫')
        else:
            out.append('（'+t+'）')
    return ''.join(out)
